properties.query:
let bf_events = SigninLogs | where ResultType == 50126 | summarize bf_count=count(), bf_time=min(TimeGenerated) by UserPrincipalName, IpAddress | where bf_count > 10;
let takeover_events = SigninLogs | where ResultType == 0 and TimeGenerated > ago(1h) | summarize takeover_time=min(TimeGenerated) by UserPrincipalName, IpAddress;
bf_events | join kind=inner takeover_events on UserPrincipalName | where takeover_time - bf_time between (0min .. 60min)
